<html lang="en">
  <head>
    <meta charset="UTF-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1.0" />
    <title>Support Contact Form</title>
    <style>
      :root {
        color-scheme: dark;
        --bg: #0b1020;
        --panel: rgba(17, 24, 39, 0.92);
        --panel-border: rgba(148, 163, 184, 0.2);
        --text: #e5eefc;
        --muted: #94a3b8;
        --accent: #7c3aed;
        --accent-strong: #8b5cf6;
        --danger: #fb7185;
        --success: #34d399;
        --shadow: 0 24px 70px rgba(2, 6, 23, 0.45);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        display: grid;
        place-items: center;
        padding: 32px 16px;
        font-family: Arial, Helvetica, sans-serif;
        background:
          radial-gradient(circle at top, rgba(124, 58, 237, 0.22), transparent 35%),
          linear-gradient(180deg, #020617 0%, #0f172a 100%);
        color: var(--text);
      }

      .support-shell {
        width: min(100%, 680px);
        background: var(--panel);
        border: 1px solid var(--panel-border);
        border-radius: 24px;
        padding: 32px;
        box-shadow: var(--shadow);
        backdrop-filter: blur(14px);
      }

      h1 {
        margin: 0 0 12px;
        font-size: clamp(2rem, 4vw, 2.5rem);
      }

      .intro {
        margin: 0 0 28px;
        color: var(--muted);
        line-height: 1.6;
      }

      form {
        display: grid;
        gap: 20px;
      }

      .form-field {
        display: grid;
        gap: 8px;
      }

      label {
        font-weight: 700;
      }

      input {
        width: 100%;
        border: 1px solid rgba(148, 163, 184, 0.28);
        border-radius: 14px;
        padding: 14px 16px;
        font-size: 1rem;
        color: var(--text);
        background: rgba(15, 23, 42, 0.95);
        transition: border-color 0.2s ease, box-shadow 0.2s ease, transform 0.2s ease;
      }

      input::placeholder {
        color: #64748b;
      }

      input:focus {
        outline: none;
        border-color: var(--accent-strong);
        box-shadow: 0 0 0 4px rgba(124, 58, 237, 0.18);
        transform: translateY(-1px);
      }

      .helper-text,
      .error-text,
      .status-text {
        font-size: 0.92rem;
        line-height: 1.5;
      }

      .helper-text {
        color: var(--muted);
      }

      .error-text {
        min-height: 1.4em;
        color: var(--danger);
      }

      .form-field.invalid input {
        border-color: rgba(251, 113, 133, 0.9);
        box-shadow: 0 0 0 4px rgba(251, 113, 133, 0.12);
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 14px 22px;
        width: fit-content;
        min-width: 160px;
        font-size: 1rem;
        font-weight: 700;
        color: white;
        background: linear-gradient(135deg, var(--accent) 0%, #2563eb 100%);
        cursor: pointer;
        box-shadow: 0 14px 34px rgba(37, 99, 235, 0.28);
        transition: transform 0.2s ease, box-shadow 0.2s ease, filter 0.2s ease;
      }

      button:hover {
        filter: brightness(1.05);
        transform: translateY(-1px);
      }

      button:focus-visible {
        outline: 3px solid rgba(139, 92, 246, 0.4);
        outline-offset: 3px;
      }

      .status-text {
        min-height: 1.5em;
        margin: 0;
        color: var(--success);
      }

      @media (max-width: 640px) {
        .support-shell {
          padding: 24px 18px;
          border-radius: 20px;
        }
      }
    </style>
  </head>
  <body>
    <main class="support-shell">
      <h1>Contact Support</h1>
      <p class="intro">
        Share your details and our support team will follow up as soon as possible.
      </p>

      <form id="support-form" novalidate>
        <div class="form-field">
          <label for="full-name">Full name</label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            placeholder="Jordan Lee"
            required
            aria-describedby="full-name-error"
          />
          <div id="full-name-error" class="error-text" aria-live="polite"></div>
        </div>

        <div class="form-field">
          <label for="email-address">Email address</label>
          <input
            id="email-address"
            name="email"
            type="email"
            autocomplete="email"
            placeholder="jordan@example.com"
            required
            aria-describedby="email-address-error"
          />
          <div id="email-address-error" class="error-text" aria-live="polite"></div>
        </div>

        <div class="form-field">
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phone"
            type="tel"
            autocomplete="tel"
            placeholder="(555) 123-4567"
            pattern="^\+?[0-9()\-\s]{7,20}$"
            aria-describedby="phone-number-help phone-number-error"
          />
          <div id="phone-number-help" class="helper-text">
            Optional. Use digits with spaces, dashes, parentheses, or a leading +, for example
            (555) 123-4567.
          </div>
          <div id="phone-number-error" class="error-text" aria-live="polite"></div>
        </div>

        <button type="submit">Submit request</button>
        <p id="form-status" class="status-text" aria-live="polite"></p>
      </form>
    </main>

    <script>
      const form = document.getElementById("support-form");
      const statusText = document.getElementById("form-status");
      const fields = Array.from(form.querySelectorAll("input"));

      const messages = {
        fullName: {
          valueMissing: "Enter your full name."
        },
        email: {
          valueMissing: "Enter your email address.",
          typeMismatch: "Enter a valid email address."
        },
        phone: {
          patternMismatch: "Use a valid phone number format, such as (555) 123-4567."
        }
      };

      function getErrorElement(field) {
        return document.getElementById(`${field.id}-error`);
      }

      function getMessage(field) {
        const fieldMessages = messages[field.name];

        if (!fieldMessages) {
          return "";
        }

        if (field.validity.valueMissing) {
          return fieldMessages.valueMissing || "";
        }

        if (field.validity.typeMismatch) {
          return fieldMessages.typeMismatch || "";
        }

        if (field.validity.patternMismatch) {
          return fieldMessages.patternMismatch || "";
        }

        return "";
      }

      function setFieldState(field) {
        const errorElement = getErrorElement(field);
        const fieldWrapper = field.closest(".form-field");
        const message = field.validity.valid ? "" : getMessage(field);

        errorElement.textContent = message;
        fieldWrapper.classList.toggle("invalid", Boolean(message));
        field.setAttribute("aria-invalid", message ? "true" : "false");
      }

      fields.forEach((field) => {
        field.addEventListener("blur", () => {
          setFieldState(field);
        });

        field.addEventListener("input", () => {
          if (getErrorElement(field).textContent) {
            setFieldState(field);
          }
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        statusText.textContent = "";

        fields.forEach(setFieldState);

        const firstInvalidField = fields.find((field) => !field.validity.valid);

        if (firstInvalidField) {
          firstInvalidField.focus();
          return;
        }

        statusText.textContent = "Your support request is ready to send.";
        form.reset();

        fields.forEach((field) => {
          field.closest(".form-field").classList.remove("invalid");
          field.setAttribute("aria-invalid", "false");
          getErrorElement(field).textContent = "";
        });
      });
    </script>
  </body>
</html>
